#!/usr/bin/env python3
"""
Validation script for pipeline outputs.
Checks that all expected output files exist, have correct structure,
and contain valid data.
"""

import json
import os
import sys
from pathlib import Path

import pandas as pd


def check_file_exists(file_path: str) -> dict:
    """Check if a file exists."""
    exists = os.path.exists(file_path)
    return {
        "check_name": f"File exists: {os.path.basename(file_path)}",
        "passed": exists,
        "message": f"File {'exists' if exists else 'does not exist'}: {file_path}"
    }


def check_file_not_empty(file_path: str) -> dict:
    """Check if a file is not empty (has data)."""
    try:
        if not os.path.exists(file_path):
            return {
                "check_name": f"File not empty: {os.path.basename(file_path)}",
                "passed": False,
                "message": "Cannot check: file does not exist"
            }

        ext = Path(file_path).suffix
        if ext == '.csv':
            df = pd.read_csv(file_path)
            row_count = len(df)
            return {
                "check_name": f"File not empty: {os.path.basename(file_path)}",
                "passed": row_count > 0,
                "message": f"File has {row_count} rows"
            }
        elif ext == '.json':
            with open(file_path, 'r') as f:
                data = json.load(f)
            return {
                "check_name": f"File not empty: {os.path.basename(file_path)}",
                "passed": data is not None,
                "message": "File contains data"
            }
    except Exception as e:
        return {
            "check_name": f"File not empty: {os.path.basename(file_path)}",
            "passed": False,
            "message": f"Error reading file: {str(e)}"
        }


def check_columns_match(file_path: str, expected_columns: list) -> dict:
    """Check if file has expected columns."""
    try:
        if not os.path.exists(file_path):
            return {
                "check_name": f"Columns match: {os.path.basename(file_path)}",
                "passed": False,
                "message": "Cannot check: file does not exist"
            }

        df = pd.read_csv(file_path)
        actual_columns = list(df.columns)
        columns_match = set(expected_columns) == set(actual_columns)

        return {
            "check_name": f"Columns match: {os.path.basename(file_path)}",
            "passed": columns_match,
            "message": f"Expected {len(expected_columns)} columns, found {len(actual_columns)}. Match: {columns_match}"
        }
    except Exception as e:
        return {
            "check_name": f"Columns match: {os.path.basename(file_path)}",
            "passed": False,
            "message": f"Error checking columns: {str(e)}"
        }


def check_row_count(file_path: str, min_rows: int) -> dict:
    """Check if file has at least min_rows rows."""
    try:
        if not os.path.exists(file_path):
            return {
                "check_name": f"Row count >= {min_rows}: {os.path.basename(file_path)}",
                "passed": False,
                "message": "Cannot check: file does not exist"
            }

        df = pd.read_csv(file_path)
        row_count = len(df)
        passed = row_count >= min_rows

        return {
            "check_name": f"Row count >= {min_rows}: {os.path.basename(file_path)}",
            "passed": passed,
            "message": f"File has {row_count} rows (minimum: {min_rows})"
        }
    except Exception as e:
        return {
            "check_name": f"Row count >= {min_rows}: {os.path.basename(file_path)}",
            "passed": False,
            "message": f"Error checking row count: {str(e)}"
        }


def validate_t01_selected_indicators():
    """Validate t01_selected_indicators.csv."""
    file_path = os.path.join("outputs", "t01_selected_indicators.csv")
    checks = []

    checks.append(check_file_exists(file_path))
    checks.append(check_file_not_empty(file_path))
    checks.append(check_columns_match(file_path, ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]))
    checks.append(check_row_count(file_path, min_rows=10))

    return checks


def validate_t05_clean_stops():
    """Validate t05_clean_stops.csv."""
    file_path = os.path.join("outputs", "t05_clean_stops.csv")
    checks = []

    checks.append(check_file_exists(file_path))
    checks.append(check_file_not_empty(file_path))
    checks.append(check_columns_match(file_path, ["stop_id", "stop_name", "stop_lat", "stop_lon"]))
    checks.append(check_row_count(file_path, min_rows=400))

    return checks


def validate_t08_pois_clean():
    """Validate t08_pois_clean.csv."""
    file_path = os.path.join("outputs", "t08_pois_clean.csv")
    checks = []

    checks.append(check_file_exists(file_path))
    checks.append(check_file_not_empty(file_path))
    checks.append(check_columns_match(file_path, ["qid", "label", "poi_type", "latitude", "longitude", "source"]))
    checks.append(check_row_count(file_path, min_rows=40))

    return checks


def validate_t10_accessibility_scores():
    """Validate t10_accessibility_scores.csv."""
    file_path = os.path.join("outputs", "t10_accessibility_scores.csv")
    checks = []

    checks.append(check_file_exists(file_path))
    checks.append(check_file_not_empty(file_path))
    checks.append(check_columns_match(file_path, ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]))
    checks.append(check_row_count(file_path, min_rows=40))

    return checks


def validate_t13_city_clusters():
    """Validate t13_city_clusters.csv."""
    file_path = os.path.join("outputs", "t13_city_clusters.csv")
    checks = []

    checks.append(check_file_exists(file_path))
    checks.append(check_file_not_empty(file_path))
    checks.append(check_columns_match(file_path, ["city_id", "city_name", "cluster_id", "cluster_name", "population"]))
    checks.append(check_row_count(file_path, min_rows=5))

    return checks


def main():
    """Main validation function."""
    all_checks = []

    all_checks.extend(validate_t01_selected_indicators())
    all_checks.extend(validate_t05_clean_stops())
    all_checks.extend(validate_t08_pois_clean())
    all_checks.extend(validate_t10_accessibility_scores())
    all_checks.extend(validate_t13_city_clusters())

    # Write validation summary as JSON list
    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(all_checks, f, indent=2)

    passed = sum(1 for c in all_checks if c["passed"])
    total = len(all_checks)
    print(f"Validation complete: {passed}/{total} checks passed")

    return 0 if passed == total else 1


if __name__ == "__main__":
    sys.exit(main())
